export type StudyLanguage = 'en' | 'vi';

export type StudyMethod = {
  name: string;
  owner: string;
  explanation: Record<StudyLanguage, string>;
};

export type StudySlide = {
  id: string;
  section: string;
  title: Record<StudyLanguage, string>;
  focus: Record<StudyLanguage, string>;
  code: string;
  language: string;
  explanation: Record<StudyLanguage, string>;
  concepts: Record<StudyLanguage, string[]>;
  methods: StudyMethod[];
  output: Record<StudyLanguage, string>;
};

export type StudyChapter = {
  id: string;
  chapter: number;
  title: Record<StudyLanguage, string>;
  theme: Record<StudyLanguage, string>;
  slides: StudySlide[];
};

export type MethodGroup = {
  id: string;
  title: Record<StudyLanguage, string>;
  module: string;
  klass: string;
  methods: Array<{
    name: string;
    code: string;
    explanation: Record<StudyLanguage, string>;
    output: Record<StudyLanguage, string>;
  }>;
};

const m = (name: string, owner: string, en: string, vi: string): StudyMethod => ({
  name,
  owner,
  explanation: { en, vi },
});

const slide = (
  id: string,
  section: string,
  titleEn: string,
  titleVi: string,
  focusEn: string,
  focusVi: string,
  code: string,
  language: string,
  explanationEn: string,
  explanationVi: string,
  conceptsEn: string[],
  conceptsVi: string[],
  methods: StudyMethod[],
  outputEn: string,
  outputVi: string
): StudySlide => ({
  id,
  section,
  title: { en: titleEn, vi: titleVi },
  focus: { en: focusEn, vi: focusVi },
  code,
  language,
  explanation: { en: explanationEn, vi: explanationVi },
  concepts: { en: conceptsEn, vi: conceptsVi },
  methods,
  output: { en: outputEn, vi: outputVi },
});

