function enrichChapter(chapter: StudyChapter): StudyChapter {
  const cases = caseStudiesByChapter[chapter.chapter] || baseCases(chapter.chapter);
  return {
    ...chapter,
    slides: [
      ...chapter.slides,
      ...cases.map((caseStudy, index) => cs(chapter.chapter, index + 1, caseStudy)),
    ],
  };
}

export const fullStudyChapters: StudyChapter[] = [
  ...studyChapters,
  ...chapterSummaries.map(buildChapter),
].map(enrichChapter);

